using Nerdy.Contracts;

namespace Nerdy.Api.Data.Entities;

// Server copies of the personal, synced entities. They mirror the DTOs in Nerdy.Contracts/Sync.cs
// plus the owner and the sync version that last changed them (see "Sync protocol" in docs/ARCHITECTURE.md).
// References between synced rows (SubjectId, TopicId, SubtopicId, ...) are deliberately not foreign keys: rows arrive
// in any order, deletes are soft, and the client owns referential integrity.

public abstract class SyncEntity
{
    /// <summary>Generated by the client.</summary>
    public Guid Id { get; set; }
    public Guid UserId { get; set; }
    /// <summary>The owner's <see cref="UserSyncState.Version"/> at which this row was last written.</summary>
    public long Version { get; set; }
    /// <summary>Stamped by the client on every edit; drives last-write-wins.</summary>
    public DateTimeOffset UpdatedAt { get; set; }
    public bool IsDeleted { get; set; }
}

public sealed class Subject : SyncEntity
{
    public string Name { get; set; } = "";
    public string ColorHex { get; set; } = "";
    public string? DueTitle { get; set; }
    public DateTimeOffset? DueAt { get; set; }
    public int SortOrder { get; set; }
}

public sealed class Topic : SyncEntity
{
    public Guid SubjectId { get; set; }
    public string Name { get; set; } = "";
    public int SortOrder { get; set; }
}

public sealed class Subtopic : SyncEntity
{
    public Guid TopicId { get; set; }
    public string Name { get; set; } = "";
    public int Progress { get; set; }
    public int SortOrder { get; set; }
}

public sealed class CalendarEvent : SyncEntity
{
    public string Title { get; set; } = "";
    public string? Subtitle { get; set; }
    public Guid? SubjectId { get; set; }
    public Guid? TopicId { get; set; }
    public DateTimeOffset StartsAt { get; set; }
    public DateTimeOffset EndsAt { get; set; }
    public bool IsAllDay { get; set; }
    public bool IsMilestone { get; set; }
    public int RepeatDays { get; set; }
    public DateOnly? RepeatUntil { get; set; }
    public int? ReminderMinutes { get; set; }
    public bool AutoFocus { get; set; }
    public FocusMode AutoFocusMode { get; set; }
    public Guid? SeriesId { get; set; }
}

public sealed class Reminder : SyncEntity
{
    public string Title { get; set; } = "";
    public DateTimeOffset? DueAt { get; set; }
    public bool HasDueTime { get; set; }
    public Guid? SubjectId { get; set; }
    public Guid? TopicId { get; set; }
    public bool IsStarred { get; set; }
    public bool IsDone { get; set; }
    public DateTimeOffset? CompletedAt { get; set; }
    public string? Notes { get; set; }
}

public sealed class Note : SyncEntity
{
    public string Title { get; set; } = "";
    public Guid? SubjectId { get; set; }
    public Guid? TopicId { get; set; }
    public Guid? SubtopicId { get; set; }
    public string BodyRtf { get; set; } = "";
    public string BodyText { get; set; } = "";
    /// <summary><see cref="ChecklistItemDto"/>[] serialized as JSON text.</summary>
    public string ChecklistJson { get; set; } = "[]";
}

public sealed class FocusSession : SyncEntity
{
    public Guid? SubjectId { get; set; }
    public Guid? TopicId { get; set; }
    public string Task { get; set; } = "";
    public FocusMode Mode { get; set; }
    public int PlannedSeconds { get; set; }
    public int ActualSeconds { get; set; }
    public DateTimeOffset StartedAt { get; set; }
    public DateTimeOffset EndedAt { get; set; }
    public FocusOutcome Outcome { get; set; }
    public ExitReason? ExitReason { get; set; }
    public string? ExitNote { get; set; }
}

/// <summary>One opaque JSON document per user; the app owns its schema.</summary>
public sealed class UserPreferences
{
    public Guid UserId { get; set; }
    public string Json { get; set; } = "{}";
    public DateTimeOffset UpdatedAt { get; set; }
    public long Version { get; set; }
}

/// <summary>The per-user sync counter. <see cref="Version"/> is a concurrency token so concurrent syncs serialize.</summary>
public sealed class UserSyncState
{
    public Guid UserId { get; set; }
    public long Version { get; set; }
}
